<script setup lang="ts">import{useAuthStore}from'../stores/auth';const auth=useAuthStore()</script><template><section class="page-head"><div><h2>个人中心</h2><p>当前登录账户的真实身份信息。</p></div></section><article class="panel profile-card"><div class="avatar large">{{auth.user?.displayName?.slice(0,1)}}</div><div><small>姓名</small><b>{{auth.user?.displayName}}</b></div><div><small>邮箱</small><b>{{auth.user?.email}}</b></div><div><small>角色</small><b>{{auth.user?.role}}</b></div><button class="outline-button" @click="auth.logout">退出登录</button></article></template>
